/**
 * One page of a Patient's $everything: a FHIR R4 searchset Bundle of the Patient (first
 * page), Observations, Devices and Provenance.
 */
export interface FHIREverythingBundle {
  resourceType: "Bundle";
  type: "searchset";
  link: FHIRBundleLink[];
  /** Absent on an empty page after the first. */
  entry?: FHIREverythingBundleEntry[];
}

export interface FHIREverythingBundleEntry {
  fullUrl: string;
  resource: FHIRPatient | FHIRObservation | FHIRDevice | FHIRProvenance;
  search?: FHIREverythingBundleEntrySearch;
}

export interface FHIREverythingBundleEntrySearch {
  mode?: "match" | "include";
}

/**
 * One Open mHealth data point (omh:data-point:1.0): a header (omh:header:1.2) and a body
 * that follows the schema `header.schema_id` names (docs/open-mhealth.md).
 */
export interface OMHDataPoint {
  header: OMHDataPointHeader;
  /** The measure, in the shape of its schema. */
  body: Record<string, unknown>;
}

export interface OMHDataPointHeader {
  /** The record's id, the same as its FHIR Observation id (`qs-`, `bp-`, `sleep-`, `workout-`). */
  id: string;
  /** When the record was stored. */
  creation_date_time: string;
  schema_id: OMHDataPointHeaderSchemaId;
  acquisition_provenance: OMHDataPointHeaderAcquisitionProvenance;
  user_id: string;
}

export interface OMHDataPointHeaderSchemaId {
  namespace: "omh";
  name: string;
  version: string;
}

export interface OMHDataPointHeaderAcquisitionProvenance {
  /** The provider the record came from. */
  source_name: string;
  /** The provider's own id of the record. */
  source_data_point_id?: string;
  modality?: "sensed" | "self-reported";
}

export interface OMHDataPointPage {
  data: OMHDataPoint[];
  /** Null on the last page. */
  next_cursor: string | null;
}

/**
 * A FHIR R4 Observation made from one quantity sample, a blood pressure pair, a sleep
 * session, a workout or a daily summary (docs/fhir.md).
 */
export interface FHIRObservation {
  resourceType: "Observation";
  id: string;
  meta?: FHIRObservationMeta;
  /** The provider's own id of the record (of each sample of a panel), when it has one. */
  identifier?: FHIRObservationIdentifier[];
  status: "final";
  category?: FHIRCodeableConcept[];
  code: FHIRCodeableConcept;
  subject: FHIRReference;
  effectiveDateTime?: string;
  effectivePeriod?: FHIRObservationEffectivePeriod;
  /** When the record was ingested (the later of a panel's two samples). */
  issued?: string;
  valueQuantity?: FHIRQuantity;
  dataAbsentReason?: FHIRCodeableConcept;
  device?: FHIRReference;
  /**
   * The two values of a blood pressure panel, or a sleep session's, workout's or daily
   * summary's other fields; a field without a value is left out.
   */
  component?: FHIRObservationComponent[];
}

export interface FHIRObservationMeta {
  /** The provider the record came through. */
  source?: string;
  profile?: string[];
  /** The vendor that produced the record, when known. */
  tag?: FHIRCoding[];
}

export interface FHIRObservationIdentifier {
  system?: string;
  value?: string;
}

export interface FHIRObservationEffectivePeriod {
  start?: string;
  end?: string;
}

export interface FHIRObservationComponent {
  code: FHIRCodeableConcept;
  valueQuantity?: FHIRQuantity;
  valueCodeableConcept?: FHIRCodeableConcept;
  dataAbsentReason?: FHIRCodeableConcept;
}

export interface FHIRQuantity {
  value?: number;
  unit?: string;
  system?: "http://unitsofmeasure.org";
  code?: string;
}

/** A FHIR R4 searchset Bundle of Observations. */
export interface FHIRBundle {
  resourceType: "Bundle";
  type: "searchset";
  link: FHIRBundleLink[];
  /** Absent on an empty page (FHIR JSON has no empty arrays). */
  entry?: FHIRBundleEntry[];
}

export interface FHIRBundleLink {
  relation: "self" | "next";
  url: string;
}

export interface FHIRBundleEntry {
  fullUrl: string;
  /**
   * A FHIR R4 Observation made from one quantity sample, a blood pressure pair, a sleep
   * session, a workout or a daily summary (docs/fhir.md).
   */
  resource: FHIRObservation;
  search?: FHIRBundleEntrySearch;
}

export interface FHIRBundleEntrySearch {
  mode?: "match";
}

